mapper.select:
select a.*
from oc_litigation_registration a
left join client b on a.client_id = b.id


        and a.client_id = #{query.clientId}


        and a.status = #{query.status}


        and a.code like concat('%',#{query.code},'%')


        and a.contract_codes like concat('%',#{query.contractCodes},'%')


        and
        (b.belong_dept_id IN

            #{item}

        OR b.belong_sponsor_id = #{query.currentUserId}
        )


order by a.update_time desc
